type JevRequest = Parameters<JevAsk>[0];

/** A Jev that answers every Noul with `noul(id)` and every Score at `level(id)`. */
function fakeJev(options: { noul?: (id: string) => number; level?: (id: string) => number } = {}) {
  const requests: JevRequest[] = [];
  const ask: JevAsk = async (request) => {
    requests.push(request);
    return {
      ok: true,
      answers: Object.fromEntries(
        Object.entries(request.questions).map(([id, q]) => {
          if (q.type === "noul") return [id, { type: "noul", noul: options.noul?.(id) ?? 0.9 }];
          const levels = q.criteria ?? [];
          const level = options.level?.(id) ?? levels.length - 1;
          return [
            id,
            {
              type: "score",
              score: level,
              confidence: 0.8,
              legend: Object.fromEntries(levels.map((text, i) => [String(i), text])),
              probabilities: { [String(level)]: 1 },
            },
          ];
        }),
      ),
    };
  };
  return { ask, requests };
}

