export interface ConstructResult {
  name: string;
  level: "case" | "item";
  evaluators: string[];
  /** Observations every evaluator scored (cases, or items). */
  n: number;
  cases: number;
  /** Each evaluator's mean on the common support. */
  means: Record<string, number>;
  pairs: AgreementPair[];
  /** AUC per evaluator against the planted answer, when there is one. */
  gold?: { name: string; positives: number; negatives: number; auc: Record<string, number | null> };
}

function readingsOf(evaluator: Evaluator, cases: CaseLike[], level: Construct["level"]): Map<string, number> {
  const out = new Map<string, number>();
  for (const c of cases) {
    const reading = evaluator.read(c);
    if (level === "case") {
      if (typeof reading === "number" && Number.isFinite(reading)) out.set(c.case_id, reading);
    } else if (reading && typeof reading === "object") {
      for (const [item, value] of Object.entries(reading))
        if (typeof value === "number" && Number.isFinite(value)) out.set(`${c.case_id}\u0000${item}`, value);
    }
  }
  return out;
}

export function agreementFor(suite: string, cases: CaseLike[]): ConstructResult[] {
  const live = cases.filter((c) => !c.skipped && c.ok !== false);
  const results: ConstructResult[] = [];
  for (const construct of CONSTRUCTS[suite] ?? []) {
    const present = construct.evaluators
      .map((e) => ({ e, values: readingsOf(e, live, construct.level) }))
      .filter((x) => x.values.size > 0);
    const goldOf = construct.gold
      ? new Map(
          live.flatMap((c) => {
            const g = construct.gold!.read(c);
            return g === null ? [] : [[c.case_id, g] as const];
          }),
        )
      : null;
    if (present.length < (goldOf?.size ? 1 : 2)) continue;
    let keys = [...present[0].values.keys()].filter((k) => present.every((x) => x.values.has(k)));
    if (goldOf?.size && construct.level === "case") keys = keys.filter((k) => goldOf.has(k));
    if (!keys.length) continue;
    const series = present.map((x) => ({ name: x.e.name, values: keys.map((k) => x.values.get(k)!) }));
    const pairs: AgreementPair[] = [];
    for (let i = 0; i < series.length; i++)
      for (let j = i + 1; j < series.length; j++)
        pairs.push(agreementPair(series[i].name, series[j].name, series[i].values, series[j].values));
    const result: ConstructResult = {
      name: construct.name,
      level: construct.level,
      evaluators: series.map((s) => s.name),
      n: keys.length,
      cases: new Set(keys.map((k) => k.split("\u0000")[0])).size,
      means: Object.fromEntries(
        series.map((s) => [s.name, s.values.reduce((a, b) => a + b, 0) / s.values.length]),
      ),
      pairs,
    };
    if (goldOf?.size && construct.level === "case") {
      const labels = keys.map((k) => goldOf.get(k)!);
      result.gold = {
        name: construct.gold!.name,
        positives: labels.filter((g) => g === 1).length,
        negatives: labels.filter((g) => g === 0).length,
        auc: Object.fromEntries(
          series.map((s) => [
            s.name,
            auc(
              s.values.filter((_, i) => labels[i] === 1),
              s.values.filter((_, i) => labels[i] === 0),
            ),
          ]),
        ),
      };
    }
    results.push(result);
  }
  return results;
}

const f2 = (x: number | null | undefined) => (typeof x === "number" && Number.isFinite(x) ? x.toFixed(2) : "  -");

export function formatAgreement(results: ConstructResult[]): string[] {
  if (!results.length) return [];
  const lines = ["  evaluator agreement (on the cases every evaluator scored)"];
  for (const r of results) {
    const unit = r.level === "item" ? `${r.n} items in ${r.cases} cases` : `${r.n} cases`;
    lines.push(
      `    ${r.name} (${unit}); means ${Object.entries(r.means).map(([k, v]) => `${k} ${v.toFixed(2)}`).join(", ")}`,
    );
    for (const p of r.pairs)
      lines.push(
        `      ${`${p.a} ~ ${p.b}`.padEnd(46)} r ${f2(p.pearson)}  ρ ${f2(p.spearman)}  agree ${f2(p.agree)}  κ ${f2(p.kappa)}  Δ ${p.meanDiff === null ? "-" : (p.meanDiff >= 0 ? "+" : "−") + Math.abs(p.meanDiff).toFixed(2)}`,
      );
    if (r.gold)
      lines.push(
        `      AUC vs ${r.gold.name} (${r.gold.positives}/${r.gold.negatives}): ${Object.entries(r.gold.auc).map(([k, v]) => `${k} ${f2(v)}`).join(", ")}`,
      );
  }
  return lines;
}
/**
 * Reading app eval reports back: for `--baseline`, and for `compare.ts`.
 *
 * A report spec is a report file, a directory of them, or a path prefix
 * (`reports/app-evals/notorganic-fixed-20261023` picks up every suite of that
 * run). Several reports of one suite, such as the rounds of `--repeat`, merge
 * into one case per case_id holding each metric's mean across the runs, which
 * is the less noisy baseline to compare against.
 */
import { existsSync, readdirSync, readFileSync, statSync } from "node:fs";
import { basename, dirname, join } from "node:path";
import type { CaseLike } from "./stats";

/** The parts of a report this module reads; run.ts's SuiteReport fits it. */
export interface ReportLike {
  suite: string;
  experiment?: string;
  model?: string;
  judge?: string;
  startedAt?: string;
  cases: CaseLike[];
}

export function reportPaths(spec: string): string[] {
  if (existsSync(spec) && statSync(spec).isDirectory())
    return readdirSync(spec)
      .filter((name) => name.endsWith(".json") && !name.endsWith("-repeatability.json"))
      .sort()
      .map((name) => join(spec, name));
  if (existsSync(spec)) return [spec];
  const dir = dirname(spec);
  const prefix = basename(spec);
  if (!existsSync(dir)) return [];
  return readdirSync(dir)
    .filter((name) => name.startsWith(prefix) && name.endsWith(".json") && !name.endsWith("-repeatability.json"))
    .sort()
    .map((name) => join(dir, name));
}

export function readReports(specs: string[]): ReportLike[] {
  const paths = [...new Set(specs.flatMap(reportPaths))];
  if (!paths.length) throw new Error(`No reports found for ${specs.join(", ")}`);
  return paths.flatMap((path) => {
    const parsed = JSON.parse(readFileSync(path, "utf8")) as ReportLike | ReportLike[];
    const list = Array.isArray(parsed) ? parsed : [parsed];
    return list.filter((r) => r && typeof r.suite === "string" && Array.isArray(r.cases));
  });
}

export function bySuite(reports: ReportLike[]): Map<string, ReportLike[]> {
  const out = new Map<string, ReportLike[]>();
  for (const report of reports) out.set(report.suite, [...(out.get(report.suite) ?? []), report]);
  return out;
}

/**
 * One case per case_id across several runs of a suite: each metric's score
 * is its mean over the runs that scored it. Labels, items and raw output are
 * the first run's.
 */
export function averageRuns(reports: ReportLike[]): CaseLike[] {
  if (reports.length === 1) return reports[0].cases;
  const merged = new Map<string, { first: CaseLike; sums: Map<string, { total: number; n: number }> }>();
  for (const report of reports)
    for (const c of report.cases) {
      if (c.skipped) continue;
      const entry = merged.get(c.case_id) ?? { first: c, sums: new Map() };
      for (const [name, score] of Object.entries(c.scores)) {
        if (typeof score?.score !== "number") continue;
        const sum = entry.sums.get(name) ?? { total: 0, n: 0 };
        sum.total += score.score;
        sum.n += 1;
        entry.sums.set(name, sum);
      }
      merged.set(c.case_id, entry);
    }
  return [...merged.values()].map(({ first, sums }) => ({
    ...first,
    scores: Object.fromEntries(
      [...new Set([...Object.keys(first.scores), ...sums.keys()])].map((name) => {
        const sum = sums.get(name);
        const score = first.scores[name] ?? { score: null };
        return [name, sum ? { ...score, score: sum.total / sum.n } : score];
      }),
    ),
  }));
}

export function describe(reports: ReportLike[]): string {
  const first = reports[0];
  const name = first.experiment ?? first.suite;
  return reports.length > 1 ? `${name} (+${reports.length - 1} more run(s), averaged)` : name;
}
