/** Run one batched Jev request; a failure marks every question jev-error. */
export async function askJev(
  jev: JevAsk,
  state: Record<string, string>,
  questions: Parameters<JevAsk>[0]["questions"],
): Promise<Record<string, Score>> {
  const ids = Object.keys(questions);
  try {
    const result = await jev({ state, questions });
    if (!result.ok || !result.answers)
      return Object.fromEntries(
        ids.map((id) => [id, { score: null, label: "jev-error", explanation: result.error ?? "no answer" }]),
      );
    return Object.fromEntries(
      ids.map((id) => {
        const v = readJevAnswer(result.answers?.[id]);
        return [
          id,
          {
            score: v.score,
            label: v.label ?? "jev-error",
            explanation:
              v.confidence !== null ? `Jev confidence ${v.confidence.toFixed(2)}` : "",
          },
        ];
      }),
    );
  } catch (error) {
    return Object.fromEntries(
      ids.map((id) => [
        id,
        { score: null, label: "jev-error", explanation: error instanceof Error ? error.message : String(error) },
      ]),
    );
  }
}

